// Explicit histograms passed to original HistoKeeper/computeStem, no numeric replay.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;
public class StemScaleHistogramControlProbe extends KeyBuilderProcessProbe {
 final Object book;public StemScaleHistogramControlProbe(Book b,SortedSet<Integer>ids){super(b,ids);book=b;}
 public void process(){try{
  Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),scale=call(sheet,"getScale");Class<?> scalerClass=Class.forName("org.audiveris.omr.sheet.stem.StemScaler"),rt=Class.forName("org.audiveris.omr.run.RunTable"),orientation=Class.forName("org.audiveris.omr.run.Orientation");Object horizontal=orientation.getField("HORIZONTAL").get(null);Constructor<?> ctor=Class.forName("org.audiveris.omr.sheet.stem.StemScaler$HistoKeeper").getDeclaredConstructor(scalerClass,rt,int.class);ctor.setAccessible(true);
  Map<String,int[]> inputs=new LinkedHashMap<>();inputs.put("empty",new int[17]);int[] terminal=new int[17];terminal[16]=100;inputs.put("terminal-hi",terminal);inputs.put("terminal-lo",new int[]{0,100,0});inputs.put("peak-followed-by-small-rise",new int[]{0,100,0,0,1,0,0});inputs.put("equal-peaks",new int[]{0,100,0,0,100,0,0,1,0});inputs.put("wide-peak",new int[]{0,50,100,50,0,0,1,0,0});for(int area:new int[]{1,2,5,10,15,25,30,35})inputs.put("area-"+area,new int[]{0,Math.max(0,area-1),0,0,1,0,0});inputs.put("large-bin-40000",new int[]{0,40000,0,0,3000,0,0,1,0});inputs.put("large-weighted-peaks",new int[]{0,40000,35000,0,0,50000,0,1,0});List<String> results=new ArrayList<>();
  for(var entry:inputs.entrySet()){
   Object scaler=scalerClass.getConstructor(Class.forName("org.audiveris.omr.sheet.Sheet")).newInstance(sheet),table=rt.getConstructor(orientation,int.class,int.class).newInstance(horizontal,1,1);int[] values=entry.getValue();Object keeper=ctor.newInstance(scaler,table,values.length-1);Object function=get(keeper,"function");for(int i=0;i<values.length;i++)call(function,"setValue",i,values[i]);put(scaler,"histoKeeper",keeper);Object result=call(scaler,"computeStem"),selected=get(scaler,"peak");List<String> peaks=new ArrayList<>();for(Object p:(List<?>)call(get(keeper,"peakFinder"),"getPeaks"))peaks.add("{\"min\":"+get(p,"min")+",\"main\":"+get(p,"main")+",\"max\":"+get(p,"max")+"}");results.add("{\"name\":"+q(entry.getKey())+",\"histogram\":"+Arrays.toString(values)+",\"observed_area\":"+call(function,"getArea")+",\"original_peaks\":["+String.join(",",peaks)+"],\"selected_peak\":"+(selected==null?"null":"{\"min\":"+get(selected,"min")+",\"main\":"+get(selected,"main")+",\"max\":"+get(selected,"max")+"}")+",\"stem_scale\":{\"main\":"+call(result,"getMain")+",\"max\":"+call(result,"getMax")+"}}");
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"controlled_input\":true,\"description\":\"Original HistoKeeper constructed on empty original RunTable, then explicit IntegerFunction bin values injected; original computeStem and HiLo are unmodified. Histogram xmax intentionally varies independently from source image interline.\",\"source_interline\":"+call(scale,"getInterline")+",\"foreground_main\":"+call(scale,"getFore")+",\"foreground_max\":"+call(scale,"getMaxFore")+",\"cases\":["+String.join(",",results)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
